#include <cuda_runtime.h>
#include <vector>
#include <fstream>
#include <type_traits>
#define main original_extend2_main
#include "../extend2-cuda/main.cu"
#undef main
static_assert(std::is_signed<char>::value,"Signedmatrixscores");
void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}
std::vector<int>load(const char*p){std::ifstream f(p,std::ios::binary|std::ios::ate);size_t n=f.tellg();f.seekg(0);std::vector<int>v(n/4);f.read((char*)v.data(),n);return v;}
template<class T>struct Buf{T*d;std::vector<T>h;T sent;Buf(const std::vector<T>&v,T s):sent(s){h.assign(v.size()+8,s);std::copy(v.begin(),v.end(),h.begin()+4);ck(cudaMalloc(&d,h.size()*sizeof(T)));reset();}T*ptr(){return d+4;}void reset(){ck(cudaMemcpy(d,h.data(),h.size()*sizeof(T),cudaMemcpyHostToDevice));}std::vector<T>get(){std::vector<T>r(h.size());ck(cudaMemcpy(r.data(),d,r.size()*sizeof(T),cudaMemcpyDeviceToHost));return r;}};
struct Case{std::vector<int>p;Buf<unsigned char>*q,*t;Buf<char>*mat,*qp;eh_t*eh;std::vector<eh_t>heh;Buf<int>*out;};
void run(Case&c){auto&p=c.p;int*r=c.out->ptr();kernel_extend2<<<1,1>>>(c.q->ptr(),c.t->ptr(),c.mat->ptr(),c.eh+4,c.qp->ptr(),r,r+1,r+2,r+3,r+4,r+5,p[0],p[1],p[2],p[3],p[4],p[5],p[6],p[7],p[8],p[9],p[10]);ck(cudaDeviceSynchronize());}
int main(){auto f=load(EX_FIXTURE),o=load(EX_ORACLE);std::vector<Case>cs;size_t i=0;while(i<f.size()){Case c;c.p.assign(f.begin()+i,f.begin()+i+11);i+=11;auto take=[&](int n){std::vector<unsigned char>v(f.begin()+i,f.begin()+i+n);i+=n;return v;};c.q=new Buf<unsigned char>(take(c.p[0]),0xa5);c.t=new Buf<unsigned char>(take(c.p[1]),0xa5);std::vector<char>m(f.begin()+i,f.begin()+i+25);i+=25;c.mat=new Buf<char>(m,-91);c.qp=new Buf<char>(std::vector<char>(5*c.p[0],0),-91);c.out=new Buf<int>(std::vector<int>(6,0),-819225);c.heh.assign(c.p[0]+9,{-819225,-819225});for(int j=4;j<c.p[0]+5;j++)c.heh[j]={0,0};ck(cudaMalloc(&c.eh,c.heh.size()*sizeof(eh_t)));ck(cudaMemcpy(c.eh,c.heh.data(),c.heh.size()*sizeof(eh_t),cudaMemcpyHostToDevice));cs.push_back(c);}
 for(auto&c:cs)run(c);
 for(int trial=1;trial<=5;trial++){auto payload=f;bool ok=true;double tm=0;size_t oi=0;for(auto&c:cs){ck(cudaMemcpy(c.eh,c.heh.data(),c.heh.size()*sizeof(eh_t),cudaMemcpyHostToDevice));c.qp->reset();c.out->reset();ck(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();run(c);tm+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();auto q=c.q->get(),t=c.t->get();auto m=c.mat->get(),qp=c.qp->get();auto out=c.out->get();std::vector<eh_t>eh(c.heh.size());ck(cudaMemcpy(eh.data(),c.eh,eh.size()*sizeof(eh_t),cudaMemcpyDeviceToHost));std::vector<int>h,e;for(auto v:eh){h.push_back(v.h);e.push_back(v.e);}for(int j=4;j<10;j++)ok&=out[j]==o[oi++];for(int j=4;j<c.p[0]+5;j++)ok&=h[j]==o[oi++];for(int j=4;j<c.p[0]+5;j++)ok&=e[j]==o[oi++];for(int j=4;j<5*c.p[0]+4;j++)ok&=int(qp[j])==o[oi++];ok&=q==c.q->h&&t==c.t->h&&m==c.mat->h;
 auto append=[&](auto&v,int sent){for(int j=0;j<4;j++)ok&=int(v[j])==sent;for(size_t j=v.size()-4;j<v.size();j++)ok&=int(v[j])==sent;for(auto x:v)payload.push_back(int(x));};append(q,165);append(t,165);append(m,-91);append(h,-819225);append(e,-819225);append(qp,-91);append(out,-819225);}
 std::string path="trial_"+std::to_string(trial)+".bin";std::ofstream z(path,std::ios::binary);z.write((char*)payload.data(),payload.size()*4);z.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":0,\"timing_region\":\"sum22_preallocated_serial_extension_kernels_complete\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,tm,ok?"true":"false",payload.size(),path.c_str(),payload.size());if(!ok)return 3;}}
